/**
 * Derives the OPE domain and range from the field type.
 *
 * <p>The returned array contains {@code [domain, range]} where domain is the maximum
 * value that {@link #bytesToPositiveLong(byte[])} can produce for the field's serialized
 * byte count, and range is {@code domain * 10} (capped at Long.MAX_VALUE).
 *
 * <p>The domain must match the encoding used by {@code bytesToPositiveLong} which packs
 * the byte array length and data into a positive long. For a field that serializes to
 * N bytes, the maximum encoded value is computed by {@link #maxEncodedValue(int)}.
 *
 * @param type the field type; must be OPE-compatible (numeric primitive or BoundedString)
 * @return a two-element long array {@code [domain, range]}
 * @throws IllegalArgumentException if the field type is not compatible with OPE
 */
static long[] deriveOpeBounds(FieldType type) {
    assert type != null : "type must not be null";

    final int byteCount;

    if (type instanceof FieldType.Primitive p) {
        byteCount = switch (p) {
            case INT8 -> 1;
            case INT16 -> 2;
            case INT32 -> 4;
            case INT64, TIMESTAMP -> 6; // capped to max 6 bytes (bytesToPositiveLong limit)
            default -> throw new IllegalArgumentException(
                    "OrderPreserving encryption is not supported for field type " + p);
        };
    } else if (type instanceof FieldType.BoundedString bs) {
        byteCount = Math.min(bs.maxLength(), 6);
    } else {
        throw new IllegalArgumentException(
                "OrderPreserving encryption is not supported for field type " + type);
    }

    final long domain = maxEncodedValue(byteCount);
    assert domain >= 1 : "domain must be >= 1";

    // Cap range to avoid overflow; range must be > domain
    final long range;
    if (domain > Long.MAX_VALUE / OPE_RANGE_RATIO) {
        range = Long.MAX_VALUE;
    } else {
        range = domain * OPE_RANGE_RATIO;
    }
    assert range > domain : "range must be > domain";

    return new long[]{domain, range};
}

/**
 * Computes the maximum value that {@link #bytesToPositiveLong(byte[])} can return
 * for a byte array of the given length. This defines the OPE domain upper bound.
 *
 * <p>The encoding is: {@code 1 + (length << 48) + sum(data[i] << (40 - i*8))}
 * where data[i] ranges [0..255]. Maximum value occurs when all data bytes are 0xFF.
 *
 * @param byteCount the number of data bytes (1..6)
 * @return the maximum encoded positive long for that byte count
 */
private static long maxEncodedValue(int byteCount) {
    assert byteCount >= 1 && byteCount <= 6 : "byteCount must be in [1..6]";
    long max = 1L; // base offset
    max += ((long) byteCount) << 48; // length component
    for (int i = 0; i < byteCount; i++) {
        max += 0xFFL << (40 - i * 8);
    }
    return max;
}
